#!/bin/bash
# Forgejo on a Linux VM: local only (HTTP 127.0.0.1:3000, SSH 127.0.0.1:2222), access through an SSH tunnel.
# Run as root on the server:  bash install.sh <version>     for example: bash install.sh 17.0.1
# Safe to re-run: the binary is updated, app.ini and data are left alone.
# Secrets (SECRET_KEY, INTERNAL_TOKEN, JWT) are generated by Forgejo itself into /etc/forgejo/app.ini and are not printed.
set -euo pipefail
VER=${1:?"usage: install.sh <version>"}
HERE=$(cd "$(dirname "$0")" && pwd)
ARCH=linux-amd64
URL="https://codeberg.org/forgejo/forgejo/releases/download/v${VER}/forgejo-${VER}-${ARCH}"
# Forgejo release signing key (docs: forgejo.org/docs/latest/admin/installation-binary)
KEY=EB114F5E6C0DC2BCDD183550A4B61A2DC5923710

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
echo "== download forgejo ${VER}"
curl -fsSL --retry 3 -o "$tmp/forgejo" "$URL"
curl -fsSL --retry 3 -o "$tmp/forgejo.sha256" "$URL.sha256"
curl -fsSL --retry 3 -o "$tmp/forgejo.asc" "$URL.asc"
(cd "$tmp" && echo "$(cut -d' ' -f1 forgejo.sha256)  forgejo" | sha256sum -c -)
export GNUPGHOME="$tmp/gnupg"; mkdir -m 700 "$GNUPGHOME"
gpg --batch --quiet --keyserver hkps://keys.openpgp.org --recv-keys "$KEY"
gpg --batch --verify "$tmp/forgejo.asc" "$tmp/forgejo"
install -m 755 "$tmp/forgejo" /usr/local/bin/forgejo
/usr/local/bin/forgejo --version

echo "== user and folders"
id git >/dev/null 2>&1 || adduser --system --shell /bin/bash --gecos 'Forgejo' --group --disabled-password --home /home/git git
install -d -o git -g git -m 750 /var/lib/forgejo /var/lib/forgejo/custom /var/lib/forgejo/data /var/lib/forgejo/data/repositories /var/lib/forgejo/log
install -d -o git -g git -m 750 /var/backups/forgejo
install -d -o root -g git -m 750 /etc/forgejo

if [ ! -f /etc/forgejo/app.ini ]; then
  echo "== app.ini (new, secrets generated here)"
  F=/usr/local/bin/forgejo
  sed -e "s|@SECRET_KEY@|$($F generate secret SECRET_KEY)|" \
      -e "s|@INTERNAL_TOKEN@|$($F generate secret INTERNAL_TOKEN)|" \
      -e "s|@JWT_SECRET@|$($F generate secret JWT_SECRET)|" \
      "$HERE/app.ini.template" > /etc/forgejo/app.ini
  chown root:git /etc/forgejo/app.ini
  chmod 640 /etc/forgejo/app.ini
else
  echo "== app.ini exists, kept"
fi

echo "== systemd"
install -m 644 "$HERE/forgejo.service" /etc/systemd/system/forgejo.service
install -m 755 "$HERE/backup.sh" /usr/local/sbin/forgejo-backup
install -m 644 "$HERE/forgejo-backup.service" /etc/systemd/system/forgejo-backup.service
install -m 644 "$HERE/forgejo-backup.timer" /etc/systemd/system/forgejo-backup.timer
systemctl daemon-reload
systemctl enable --now forgejo.service
systemctl enable --now forgejo-backup.timer
systemctl restart forgejo.service
sleep 3
systemctl is-active forgejo.service
ss -ltnp | grep -E '127.0.0.1:(3000|2222) ' || { echo "forgejo is not listening"; exit 1; }
echo "== done"
